package org.sleepwell.app;

import android.app.Activity;
import android.os.Bundle;
import android.widget.LinearLayout;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Reads actual stored analysis windows. No signal is manufactured for old or manual records. */
public final class EchoPeriodsActivity extends Activity {
    private final ExecutorService reader=Executors.newSingleThreadExecutor();private Records.Factory factory;private RecordEntry record;private JSONObject run;private List<JSONObject> windows=List.of();private String error="";private boolean original;private int generation;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);factory=Records.factory;original=state!=null&&state.getBoolean("original");}
    @Override protected void onResume(){super.onResume();load();}
    private void load(){int version=++generation;long id=getIntent().getLongExtra("record",0);LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Breathing experiment",this::finish);Design.text(body,"Loading recorded windows…",14,400,Design.MUTED);reader.execute(()->{try(Store store=factory.open(getApplicationContext())){android.database.sqlite.SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();RecordEntry entry;JSONObject policy;List<JSONObject> samples;try{entry=Records.get(store,id);List<JSONObject> runs=store.rows("SELECT * FROM echo_runs WHERE session=?",Long.toString(id));policy=runs.isEmpty()?null:runs.get(0);samples=store.rows("SELECT start,end AS time,rate,periodicity,quality FROM echo_periods WHERE session=? ORDER BY start",Long.toString(id));if(samples.size()>2160)throw new IllegalStateException("Too many analysis windows.");db.setTransactionSuccessful();}finally{db.endTransaction();}runOnUiThread(()->{if(isDestroyed()||version!=generation)return;record=entry;run=policy;windows=samples;error="";render();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||version!=generation)return;error="Recorded analysis could not be opened. Your night is kept.";render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Breathing experiment",this::finish);Design.space(body,12);if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(body,"Retry",true,this::load);return;}if(record==null)return;Design.text(body,RecordUi.date(record.edit.end,record.zone()),16,600,Design.INK);Design.space(body,12);if(run==null||run.optInt("enabled")==0){Design.text(body,run==null?"No experiment recorded for this night":"Experiment was off for this night",21,600,Design.INK);Design.space(body,14);Design.button(body,"Experiment settings",false,()->startActivity(RecordUi.intent(this,EchoSettingsActivity.class)));return;}
        if(record.edited||!record.awake.events.isEmpty())RecordUi.segments(body,new String[]{"Reviewed period","Original capture"},original?1:0,value->{original=value==1;render();});
        long start=original?record.rawStart:record.edit.start,end=original?record.rawEnd:record.edit.end;List<JSONObject> visible=new ArrayList<>();List<Double> rates=new ArrayList<>();int missing=0;for(JSONObject row:windows){long from=row.optLong("start"),to=row.optLong("time");if(from<start||to>end)continue;if(!original&&RecordIntervals.length(RecordIntervals.intersect(record.coverage(),from,to))!=to-from)continue;visible.add(row);if(row.isNull("rate"))missing++;else rates.add(row.optDouble("rate"));}
        Design.space(body,15);Design.text(body,"Periodic echo rate",18,600,Design.INK);Design.space(body,6);double mean=0;for(double rate:rates)mean+=rate;Design.text(body,rates.isEmpty()?"No stable estimate":String.format(Locale.getDefault(),"%.1f cycles/min",mean/rates.size()),34,700,Design.INK);Design.text(body,rates.size()+" periodic windows · "+missing+" rejected windows · "+run.optString("state"),12,400,Design.MUTED);Design.space(body,14);if(end>start)body.addView(new RecordChart(this,visible,"rate",start,end,false,record.zone()).measurement("Periodic echo rate, cycles per minute"),new LinearLayout.LayoutParams(-1,Design.dp(this,190)));Design.space(body,12);Design.text(body,"Each estimate uses a full minute of continuous echo samples. Gaps, vibration cues, weak or conflicting periods are excluded. Trimmed or marked-awake windows are omitted in the reviewed view.",13,400,Design.MUTED);Design.space(body,12);Design.text(body,"Experimental reflection periodicity, not a validated breathing measurement. Other motion or multiple people may produce a periodic echo.",13,500,Design.BROWN);Design.space(body,16);
        for(int n=0;n<Math.min(30,visible.size());n++){JSONObject row=visible.get(n);String quality=switch(row.optString("quality")){case "PERIODIC"->"Repeating echo";case "AMBIGUOUS"->"Conflicting periods";case "NO_STABLE_PERIOD"->"No stable period";default->"Insufficient signal";};Design.item(body,"wave",RecordUi.clock(this,row.optLong("start"),record.zone()),row.isNull("rate")?quality:String.format(Locale.getDefault(),"%.1f cycles/min",row.optDouble("rate")),null);}if(visible.size()>30)Design.text(body,"Chart includes all "+visible.size()+" eligible windows; first 30 listed.",12,400,Design.MUTED);Design.button(body,"Refresh recorded windows",false,this::load);
    }
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("original",original);}
    @Override protected void onDestroy(){generation++;reader.shutdownNow();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
